	// Parser converts the agent's stdout stream into a sequence of Events.
	// The returned channel must close when stdout closes. Implementations
	// must emit Started first, Finished{Success: ...} or RunError last,
	// and check scanner.Err() before emitting Finished{Success: true}.
	Parser func(stdout io.Reader) <-chan Event

	// Prepare, when set, runs before BuildCmd. It may return an updated
	// RunConfig (ExtraArgs naming files it wrote) and a cleanup that runs
	// after the process exits. An error aborts the run before anything is
	// spawned.
	Prepare func(ctx context.Context, cfg RunConfig) (RunConfig, func(), error)

	// Preflight, when set, runs before BuildCmd and refuses an environment the
	// command cannot work in (for example an agent CLI too old for the argv
	// shape BuildCmd produces), so the review fails before any paid run.
	Preflight func(ctx context.Context) error
}

// Compile-time check.
var _ AgentReviewer = (*ReviewerTemplate)(nil)

// Name returns the agent's stable identifier.
func (t *ReviewerTemplate) Name() string { return t.AgentName }

// Start spawns the agent process, wires stdout through the parser, and
// returns a Process whose Events channel streams the parsed event sequence.
//
// Returns ErrTemplateMisconfigured if AgentName, BuildCmd, or Parser is unset,
// or if BuildCmd returns nil. These are programmer errors but failing fast
// with a typed error is friendlier than a downstream nil deref — and it
// keeps Start from panicking inside a multi-agent fan-out (CU8) where one
// misconfigured template would otherwise kill the whole run.
func (t *ReviewerTemplate) Start(ctx context.Context, cfg RunConfig) (Process, error) {
	if t.AgentName == "" {
		return nil, fmt.Errorf("ReviewerTemplate.Start: %w (empty AgentName)", ErrTemplateMisconfigured)
	}
	if t.BuildCmd == nil {
		return nil, fmt.Errorf("ReviewerTemplate.Start: %w (nil BuildCmd for agent %q)", ErrTemplateMisconfigured, t.AgentName)
	}
	if t.Parser == nil {
		return nil, fmt.Errorf("ReviewerTemplate.Start: %w (nil Parser for agent %q)", ErrTemplateMisconfigured, t.AgentName)
	}
	if t.Preflight != nil {
		if err := t.Preflight(ctx); err != nil {
			return nil, fmt.Errorf("%s: %w", t.AgentName, err)
		}
	}
	cleanup := func() {}
	if t.Prepare != nil {
		prepared, done, err := t.Prepare(ctx, cfg)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", t.AgentName, err)
		}
		cfg = prepared
		if done != nil {
			cleanup = done
		}
	}
	started := false
	defer func() {
		if !started {
			cleanup()
		}
	}()
	cmd := t.BuildCmd(ctx, cfg)
	if cmd == nil {
		return nil, fmt.Errorf("ReviewerTemplate.Start: %w (BuildCmd returned nil for agent %q)", ErrTemplateMisconfigured, t.AgentName)
	}
	// Without this, a cancelled review hangs: the agent's grandchildren keep the
	// stdout pipe open after the agent is killed, so reading Events to EOF blocks
	// forever (Ctrl+C never completes).
	procutil.TerminateOnCancel(cmd)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, fmt.Errorf("%s: stdout pipe: %w", t.AgentName, err)
	}
	// Own the stderr pipe rather than using cmd.StderrPipe: cmd.Wait closes the
	// read end as soon as the agent exits, which would discard stderr the
	// capture goroutine has not read yet. Keeping the read end lets Wait drain
	// it for a bounded time even when a grandchild holds the write end open.
	stderr, stderrWriter, err := os.Pipe()
	if err != nil {
		return nil, fmt.Errorf("%s: stderr pipe: %w", t.AgentName, err)
	}
	cmd.Stderr = stderrWriter
	if err := cmd.Start(); err != nil {
		_ = stderr.Close()
		return nil, fmt.Errorf("%s: start: %w", t.AgentName, err)
	}
	_ = stderrWriter.Close() // the child holds the only write end now
	started = true
	p := &templateProcess{
		cleanup:    cleanup,
		ctx:        ctx,
		agentName:  t.AgentName,
		cmd:        cmd,
		events:     make(chan Event, 32),
		stderr:     &boundedStderrBuffer{limit: maxProcessStderrBytes},
		stderrPipe: stderr,
		stderrDone: make(chan struct{}),
	}
	go p.run(stdout, t.Parser)
	go p.captureStderr(stderr)
	return p, nil
}

// ErrTemplateMisconfigured is returned by ReviewerTemplate.Start when one of
// the required fields (AgentName, BuildCmd, Parser) is unset, or when
// BuildCmd returns nil. Use errors.Is to detect this in tests or higher
// layers (e.g., a multi-agent orchestrator that needs to skip a misconfigured
// agent rather than crashing the whole run).
var ErrTemplateMisconfigured = errors.New("ReviewerTemplate misconfigured")

// templateProcess is the shared Process implementation for ReviewerTemplate.
type templateProcess struct {
	cleanup    func()
	ctx        context.Context
	agentName  string
	cmd        *exec.Cmd
	events     chan Event
	stderr     *boundedStderrBuffer
	stderrPipe io.ReadCloser
	stderrDone chan struct{}
}

// Events returns the channel that streams parsed events from the agent process.
func (p *templateProcess) Events() <-chan Event { return p.events }

// Wait returns the agent process's exit error with bounded stderr diagnostics.
//
// Per CU2's Process contract: nil on clean exit (exit code 0); ctx.Err()
// on cancellation; ProcessError wrapping *exec.ExitError on non-zero exit
// with stderr; other types for I/O or pipe failures. ProcessError implements
// Unwrap so callers can use errors.As and errors.Is to classify.
func (p *templateProcess) Wait() error {
	// Reap first. cmd.Wait only closes pipes it created; stderr is ours, so it
	// stays readable while the capture goroutine drains what the agent wrote.
	err := p.cmd.Wait()
	if p.stderrDone != nil {
		select {
		case <-p.stderrDone:
		case <-time.After(stderrDrainTimeout):
			// A grandchild inherited stderr and outlived the agent. Close our
			// read end so the capture goroutine finishes instead of hanging the
			// review; whatever it already copied remains the diagnostic.
			if p.stderrPipe != nil {
				_ = p.stderrPipe.Close()
			}
			<-p.stderrDone
		}
		if p.stderrPipe != nil {
			_ = p.stderrPipe.Close()
		}
	}
	if p.cleanup != nil {
		p.cleanup()
		p.cleanup = nil
	}
	if err != nil && p.ctx.Err() != nil {
		return p.ctx.Err() //nolint:wrapcheck // preserve Process cancellation contract
	}
	if err != nil {
		if stderr := p.stderr.String(); stderr != "" {
			return &ProcessError{AgentName: p.agentName, Err: err, Stderr: stderr}
		}
	}
	return err //nolint:wrapcheck // interface boundary; classifyStatus needs raw type
}

func (p *templateProcess) run(stdout io.Reader, parser func(io.Reader) <-chan Event) {
	defer close(p.events)
	for ev := range parser(stdout) {
		p.events <- ev
	}
}

func (p *templateProcess) captureStderr(stderr io.Reader) {
	defer close(p.stderrDone)
	_, _ = io.Copy(p.stderr, stderr) //nolint:errcheck // stderr is best-effort diagnostic context
}

// ProcessError wraps a process failure with bounded stderr diagnostics.
// Unwrap preserves the underlying error, so callers can still use errors.As
// for *exec.ExitError or errors.Is for lower-level sentinels.
type ProcessError struct {
	AgentName string
	Err       error
	Stderr    string
}

func (e *ProcessError) Error() string {
	if e.Stderr == "" {
		return fmt.Sprintf("%s: %v", e.AgentName, e.Err)
	}
	return fmt.Sprintf("%s: %v: stderr: %s", e.AgentName, e.Err, e.Stderr)
}

func (e *ProcessError) Unwrap() error { return e.Err }

type boundedStderrBuffer struct {
	limit     int
	buf       []byte
	truncated bool
}

func (b *boundedStderrBuffer) Write(p []byte) (int, error) {
	if b.limit <= 0 {
		b.truncated = true
		return len(p), nil
	}
	remaining := b.limit - len(b.buf)
	if remaining > 0 {
		if len(p) <= remaining {
			b.buf = append(b.buf, p...)
		} else {
			b.buf = append(b.buf, p[:remaining]...)
			b.truncated = true
		}
	} else if len(p) > 0 {
		b.truncated = true
	}
	return len(p), nil
}

func (b *boundedStderrBuffer) String() string {
	out := strings.TrimSpace(string(b.buf))
	if out == "" {
		return ""
	}
	if b.truncated {
		return out + "\n[stderr truncated]"
	}
	return out
}

package transcript

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strconv"
	"time"

	"github.com/entireio/cli/internal/transcript/opencodev2"
)

// --- OpenCode format support ---
//
// OpenCode transcripts are a single JSON object (not JSONL):
//
//	{"info":{...},"messages":[{"info":{"role":"user","time":{...}},"parts":[...]}, ...]}
//
// Parts use "type" values: "text", "tool", "step-start", "step-finish".
// Tool parts store the tool name in "tool" (string) and call details in "state".

// isOpenCodeFormat checks whether content is a single JSON object with the
// OpenCode session shape (top-level "info" and "messages" keys).
func isOpenCodeFormat(content []byte) bool {
	trimmed := bytes.TrimSpace(content)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return false
	}
	// Quick structural check: unmarshal just enough to detect the keys.
	var probe struct {
		Info     *json.RawMessage `json:"info"`
		Messages *json.RawMessage `json:"messages"`
	}
	if json.Unmarshal(trimmed, &probe) != nil {
		return false
	}
	return probe.Info != nil && probe.Messages != nil
}

// openCodeMessage mirrors the OpenCode message structure for unmarshaling.
type openCodeMessage struct {
	Info  openCodeMessageInfo          `json:"info"`
	Parts []map[string]json.RawMessage `json:"parts"`
}

// openCodeMessageInfo is an assistant message's metadata. Tokens and ModelID
// are what its usage line carries; the rest is conversation structure.
type openCodeMessageInfo struct {
	ID      string            `json:"id"`
	Role    string            `json:"role"`
	Time    openCodeMsgTime   `json:"time"`
	Tokens  *openCodeMsgToken `json:"tokens"`
	ModelID string            `json:"modelID"`
}

type openCodeMsgTime struct {
	Created   int64 `json:"created"`
	Completed int64 `json:"completed"`
}

type openCodeMsgToken struct {
	Input     int              `json:"input"`
	Output    int              `json:"output"`
	Reasoning int              `json:"reasoning"`
	Cache     openCodeMsgCache `json:"cache"`
	Total     int              `json:"total"`
}

type openCodeMsgCache struct {
	Read  int `json:"read"`
	Write int `json:"write"`
}

// outputWithReasoning counts reasoning once, by the same total identity the
// OpenCode agent uses: total == input + output + cache means reasoning is
// already inside output. Any other total (or none) stores it apart.
func (t openCodeMsgToken) outputWithReasoning() int {
	if t.Total > 0 && t.Total == t.Input+t.Output+t.Cache.Read+t.Cache.Write {
		return t.Output
	}
	return t.Output + t.Reasoning
}

// OpenCode part types this package reads beyond text.
const (
	openCodePartTool       = "tool"
	openCodePartCompaction = "compaction"
)

// openCodeToolTask is OpenCode 1's subagent tool (OpenCode 2's "subagent").
const openCodeToolTask = "task"

// compactOpenCode converts a full OpenCode session JSON, either version
// (opencodev2.Normalize), into transcript lines. opts.StartLine is treated
// as a message-index offset (not a newline offset) because the OpenCode
// transcript is a single JSON object. It folds the records openCodeRecord
// gives each message, as OpenCodeAdapter streams them.
func compactOpenCode(content []byte, opts Options) ([]byte, error) {
	normalized, err := opencodev2.Normalize(bytes.TrimSpace(content))
	if err != nil {
		return nil, fmt.Errorf("converting opencode 2 export: %w", err)
	}
	var session struct {
		Messages []openCodeMessage `json:"messages"`
	}
	if err := json.Unmarshal(normalized, &session); err != nil {
		return nil, fmt.Errorf("parsing opencode session: %w", err)
	}

	messages := session.Messages
	if opts.StartLine > 0 {
		if opts.StartLine >= len(messages) {
			return []byte{}, nil
		}
		messages = messages[opts.StartLine:]
	}

	records := make([]Record, 0, len(messages))
	seen := make(map[string]bool, len(messages))
	for i, msg := range messages {
		// The fold key is the message ID. Convert also keeps a message
		// without one, or one repeating an earlier ID, as its own line.
		key := msg.Info.ID
		if key == "" || seen[key] {
			key = "\x00" + strconv.Itoa(i)
		}
		seen[key] = true
		if r, ok := openCodeRecord(key, msg); ok {
			records = append(records, r)
		}
	}
	return Fold(records, opts)
}

// openCodeRecord is msg's OpMessage under fold key key, false for a role
// other than user or assistant. An assistant message with no text or tool
// parts gets content [] (no line) when it has no tokens, and no content
// (a "content":null line) when it has some, so its usage still has a line.
// Its usage is a snapshot, so a later record replaces it whole.
func openCodeRecord(key string, msg openCodeMessage) (Record, bool) {
	r := Record{Op: OpMessage, ID: key, Role: msg.Info.Role, TS: msToTimestamp(msg.Info.Time.Created)}
	switch msg.Info.Role {
	case TypeUser:
		content, err := json.Marshal(openCodeUserBlocks(msg))
		if err != nil {
			return Record{}, false
		}
		r.Content = content
	case TypeAssistant:
		r.SourceID = msg.Info.ID
		r.Usage = &CallUsage{Model: msg.Info.ModelID}
		if t := msg.Info.Tokens; t != nil {
			r.Usage.InputTokens = int64(t.Input)
			r.Usage.OutputTokens = int64(t.outputWithReasoning())
			r.Usage.CacheReadTokens = int64(t.Cache.Read)
			r.Usage.CacheWriteTokens = int64(t.Cache.Write)
			r.Usage.ReasoningTokens = int64(t.Reasoning)
		}
		blocks := openCodeAssistantBlocks(msg)
		if len(blocks) == 0 && (r.Usage.InputTokens != 0 || r.Usage.OutputTokens != 0) {
			return r, true
		}
		content, err := json.Marshal(blocks)
		if err != nil {
			return Record{}, false
		}
		r.Content = content
	default:
		return Record{}, false
	}
	return r, true
}

// openCodeUserBlocks is a user message's text blocks, IDE context tags
// stripped; nil when it has none.
func openCodeUserBlocks(msg openCodeMessage) []json.RawMessage {
	var blocks []json.RawMessage
	for _, part := range msg.Parts {
		if unquote(part["type"]) != ContentTypeText {
			continue
		}
		text := StripIDEContextTags(unquote(part[ContentTypeText]))
		if text == "" {
			continue
		}
		tb := userTextBlock{Text: text}
		if id := part["id"]; id != nil {
			_ = json.Unmarshal(id, &tb.ID) //nolint:errcheck // best-effort
		}
		b, err := json.Marshal(tb)
		if err != nil {
			continue
		}
		blocks = append(blocks, b)
	}
	return blocks
}

// openCodeAssistantBlocks is an assistant message's text and tool_use
// blocks, the results of finished tools inlined.
func openCodeAssistantBlocks(msg openCodeMessage) []map[string]json.RawMessage {
	content := make([]map[string]json.RawMessage, 0, len(msg.Parts))

	for _, part := range msg.Parts {
		switch unquote(part["type"]) {
		case ContentTypeText:
			b, err := json.Marshal(ContentTypeText)
			if err != nil {
				continue
			}
			content = append(content, map[string]json.RawMessage{
				"type": b,
				"text": part[ContentTypeText],
			})
		case openCodePartTool:
			if block, ok := openCodeToolBlock(part); ok {
				content = append(content, block)
			}
		}
	}
	return content
}

// openCodeToolBlock is a tool part's tool_use block: its call ID, name and
// input, and its result once the tool finished.
func openCodeToolBlock(part map[string]json.RawMessage) (map[string]json.RawMessage, bool) {
	b, err := json.Marshal(ContentTypeToolUse)
	if err != nil {
		return nil, false
	}
	toolBlock := map[string]json.RawMessage{"type": b}
	if callID := part["callID"]; callID != nil {
		toolBlock["id"] = callID
	}
	if toolName := part["tool"]; toolName != nil {
		toolBlock["name"] = toolName
	}
	var state map[string]json.RawMessage
	if stateRaw := part["state"]; stateRaw == nil || json.Unmarshal(stateRaw, &state) != nil {
		return toolBlock, true
	}
	if inp := state["input"]; inp != nil {
		toolBlock["input"] = inp
	}
	if openCodeToolDone(state) {
		toolBlock["result"] = openCodeToolResult(unquote(part["tool"]), state)
	}
	return toolBlock, true
}

// openCodeToolDone reports whether a tool part's state has a result: a
// pending or running tool has none yet (a live stream shows it running).
func openCodeToolDone(state map[string]json.RawMessage) bool {
	switch unquote(state["status"]) {
	case "pending", "running":
		return false
	}
	return true
}

// openCodeToolResult builds the compact {"output":"...","status":"success"|"error"}
// object from an OpenCode tool state map.
func openCodeToolResult(tool string, state map[string]json.RawMessage) json.RawMessage {
	r := ToolResult{
		Output: unquote(state["output"]),
		Status: ToolStatusSuccess,
	}
	if s := unquote(state["status"]); s != "" && s != "completed" {
		r.Status = ToolStatusError
	}
	// The task tool records the subagent's session once it starts. Other
	// tools' metadata is not theirs to interpret.
	var metadata struct {
		SessionID string `json:"sessionId"`
	}
	if tool == openCodeToolTask && json.Unmarshal(state["metadata"], &metadata) == nil && metadata.SessionID != "" {
		r.Agent = &ToolResultAgent{ID: metadata.SessionID}
	}
	b, err := json.Marshal(r)
	if err != nil {
		return nil
	}
	return b
}

// msToTimestamp converts a Unix millisecond timestamp to an RFC3339 JSON string.
func msToTimestamp(ms int64) json.RawMessage {
	if ms == 0 {
		return nil
	}
	t := time.UnixMilli(ms).UTC()
	b, err := json.Marshal(t.Format(time.RFC3339Nano))
	if err != nil {
		return nil
	}
	return b
}

