// consume reads one snapshot line. It keeps no reference to line.
func (a *OpenCodeAdapter) consume(line []byte, out []Record) []Record {
	a.line++
	msg, ok := decodeOpenCodeSnapshot(line)
	if !ok {
		return out
	}
