	for _, raw := range messages {
		var buf bytes.Buffer
		if err := json.Compact(&buf, raw); err != nil {
			return nil, fmt.Errorf("compacting opencode message: %w", err)
		}
		lines = append(lines, buf.Bytes())
	}
	return lines, nil
