+		_ = ev
+	}
+
+	done := make(chan error, 1)
+	go func() { done <- proc.Wait() }()
+	select {
+	case waitErr := <-done:
+		if waitErr != nil {
+			t.Fatalf("Wait() error: %v", waitErr)
+		}
+	case <-time.After(2 * time.Second):
+		t.Fatal("Wait() blocked on stderr held by a grandchild after the agent exited")
+	}
