+	var cTime, eTime, kTime, uTime windows.Filetime
+	if err := windows.GetProcessTimes(h, &cTime, &eTime, &kTime, &uTime); err != nil {
+		return 0, err
+	}
+	return cTime.Nanoseconds(), nil
+}
