			t.Parallel()
			input := fmt.Appendf(nil, `{"info":{"id":"s"},"messages":[{"info":{"id":"a","role":"assistant","modelID":"model-a","tokens":%s},"parts":[]}]}`, tt.tokens)
			got, err := Convert(input, agentOpts("opencode"))
			if err != nil {
				t.Fatal(err)
			}
