				t.Fatalf("usage-only line missing: %s", got)
			}
			lines, err := Decode(got)
			if err != nil {
				t.Fatal(err)
			}
			if len(lines) != 1 {
				t.Fatalf("got %d lines, want 1", len(lines))
			}
