 steps:=[]struct{model,tokens string; output,read,write,reasoning int64; visible,changed bool}{
  {"model-a",`{}`,0,0,0,0,false,true},
  {"model-a",`{"input":10,"output":80,"reasoning":40,"cache":{"read":5,"write":2}}`,120,5,2,40,true,true},
  {"model-a",`{"input":10,"output":80,"reasoning":40,"cache":{"read":5,"write":2}}`,120,5,2,40,true,false},
  {"model-b",`{"input":10,"output":5}`,5,0,0,0,true,true},
 }
 for i,step:=range steps {
  export:=fmt.Appendf(nil,`{"info":{"id":"s","location":{"directory":"/repo"}},"messages":[{"id":"a","type":"assistant","model":{"id":%q,"providerID":"test"},"tokens":%s,"content":[]}]}`,step.model,step.tokens)
  records,err:=adapter.FeedExport(export);if err!=nil{t.Fatal(err)}
  if (len(records)>0)!=step.changed{t.Fatalf("step %d: unexpected records: %+v",i,records)}
  if _,err:=folder.Apply(records);err!=nil{t.Fatal(err)}
  raw,visible:=folder.Line("a");if visible!=step.visible{t.Fatalf("step %d visible=%v, want %v",i,visible,step.visible)}
  converted,err:=Convert(export,agentOpts("opencode"));if err!=nil{t.Fatal(err)}
  if !bytes.Equal(bytes.TrimSpace(raw),bytes.TrimSpace(converted)){t.Fatalf("step %d differs from Convert",i)}
  if !visible{continue}
  lines,err:=Decode(raw);if err!=nil{t.Fatal(err)}
  if len(lines)!=1{t.Fatalf("step %d: got %d lines",i,len(lines))}
  line:=lines[0]
  if line.Model!=step.model || line.InputTokens!=10 || line.OutputTokens!=step.output || line.CacheReadTokens!=step.read || line.CacheWriteTokens!=step.write || line.ReasoningTokens!=step.reasoning {
   t.Fatalf("step %d: incorrect usage snapshot: %+v",i,line)
  }
 }
}
EOF
