// ClearSessionState removes the session state file for the given session ID.
// This simulates what happens when a user commits their changes (session is "completed").
// Used in tests to allow sequential sessions to run without triggering concurrent session warnings.
func (env *TestEnv) ClearSessionState(sessionID string) error {
	env.T.Helper()

	// Session state is stored in .git/entire-sessions/<session-id>.json
	stateFile := filepath.Join(env.RepoDir, ".git", "entire-sessions", sessionID+".json")

	if err := os.Remove(stateFile); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to clear session state: %w", err)
	}
	return nil
}

// HookOutput contains the result of running a hook.
type HookOutput struct {
	Stdout []byte
	Stderr []byte
	Err    error
}

// runAgentHookWithOutput runs a hook for the given agent and returns stdout/stderr separately.
func (r *HookRunner) runAgentHookWithOutput(agentName, hookName string, inputJSON []byte) HookOutput {
	cmd := exec.CommandContext(context.Background(), getTestBinary(), "hooks", agentName, hookName)
	cmd.Dir = r.RepoDir
	cmd.Stdin = bytes.NewReader(inputJSON)
	cmd.Env = append(testutil.GitIsolatedEnv(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+r.ClaudeProjectDir,
		"GOCACHE=/tmp/go-build",
	)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	return HookOutput{
		Stdout: stdout.Bytes(),
		Stderr: stderr.Bytes(),
		Err:    err,
	}
}

// runShellHookCommandWithOutput runs an installed hook shell command exactly as written
// in the hook file and returns stdout/stderr separately.
func (r *HookRunner) runShellHookCommandWithOutput(command string, inputJSON []byte, extraEnv ...string) HookOutput {
	cmd := exec.CommandContext(context.Background(), "/bin/sh", "-c", command)
	cmd.Dir = r.RepoDir
	cmd.Stdin = bytes.NewReader(inputJSON)
	cmd.Env = append(testutil.GitIsolatedEnv(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+r.ClaudeProjectDir,
		"GOCACHE=/tmp/go-build",
	)
	cmd.Env = append(cmd.Env, extraEnv...)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	return HookOutput{
		Stdout: stdout.Bytes(),
		Stderr: stderr.Bytes(),
		Err:    err,
	// agent.EnableHomeProbes). A spawned binary is not under `go test`, so
	// without this it would start whatever claude the developer has on PATH;
	// a test that exercises the probe points it at a fake one instead.
	if err := os.Setenv("ENTIRE_TEST_CLAUDE_CONFIG_PROBE", "off"); err != nil {
		fmt.Fprintf(os.Stderr, "failed to disable the claude config probe: %v\n", err)
		os.RemoveAll(tmpDir)
		os.Exit(1)
	}

	moduleRoot := findModuleRoot()
	buildCmd := exec.CommandContext(context.Background(), "go", "build", "-o", testBinaryPath, ".")
	buildCmd.Dir = filepath.Join(moduleRoot, "cmd", "entire")

	buildOutput, err := buildCmd.CombinedOutput()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to build CLI binary: %v\nOutput: %s\n", err, buildOutput)
		os.RemoveAll(tmpDir)
		os.Exit(1)
	}

	// Warm the binary before any test deadline is running. First exec of a
	// freshly built ~65MB binary costs ~0.6s idle on darwin/arm64 (page-in plus
	// codesign validation, once per newly written file) and several seconds
	// under this suite's own parallel -race load, against 0.03s once warm. The
	// build is immediately above, so otherwise the first test to spawn the
	// binary pays that inside its own timeout — and the victim is whoever the
	// scheduler starts first. TestExternalCommand_SigintReachesPlugin allows 3s
	// for its plugin to signal ready, which is the budget that actually broke.
	//
	// A failed warm-up only restores that previous behaviour, so it warns
	// rather than exiting: an optimization must not become a new way for the
	// whole package to fail. The bound is here for the same reason — a hang
	// would otherwise stall the package until `go test -timeout` panics it,
	// pointing at TestMain rather than at the cause.
	warmCtx, cancelWarm := context.WithTimeout(context.Background(), 60*time.Second)
	warmCmd := execx.NonInteractive(warmCtx, testBinaryPath, "--version")
	if warmOutput, warmErr := warmCmd.CombinedOutput(); warmErr != nil {
		fmt.Fprintf(os.Stderr, "warning: could not warm CLI binary: %v\nOutput: %s\n", warmErr, warmOutput)
	}
	cancelWarm()

	// Run tests
	code := m.Run()

	// Cleanup
	os.RemoveAll(tmpDir)
	os.Exit(code)
}

